/*
 * Denji — módulo autocontenido del asistente de VólticvS.
 *
 * Uso: JC solo agrega esta línea al final de su <body>, nada más:
 *     <script src="denji.js"></script>
 *
 * Qué hace solo, sin que JC configure nada:
 *  - Inyecta su propio CSS (todo prefijado "denji-", no choca con los estilos de JC)
 *  - Crea sus propios elementos (sprite, burbuja de texto, barra de progreso)
 *  - Lee el HTML de JC buscando las etiquetas de texto conocidas para saber
 *    hacia dónde caminar (ver ETIQUETAS más abajo)
 *  - Corre la encuesta completa: accesibilidad, ubicación, 8 preguntas base,
 *    puerta a la versión extendida, 10 preguntas avanzadas, resumen final
 *
 * Limitación real, no maquillada: la búsqueda de "hacia dónde caminar" es por
 * texto conocido, no comprensión real de cualquier página. Si JC cambia el
 * texto de una etiqueta, hay que actualizar ETIQUETAS acá abajo. Una versión
 * que entienda cualquier HTML sin curaduría previa requeriría mandarle el DOM
 * a un LLM en tiempo real (ej. Groq) — eso es una fase aparte, no esto.
 */
(function(){
  'use strict';

  const SPRITE_IDLE_B64 = "";
  const SPRITE_WALK_B64 = "";
  const SPRITE_TALK_B64 = "";
  const SPRITE_SALUDO_B64 = "";

  // ---------- CSS propio, inyectado, todo prefijado denji- ----------
  const css = `
    #denji-sprite{position:fixed;width:68px;height:100px;left:40px;top:60vh;object-fit:contain;box-shadow:0 1px 3px rgba(0,0,0,.25);z-index:9999;pointer-events:none;transition:none}
    @keyframes denji-walk-bounce{0%,100%{transform:translateY(0)}50%{transform:translateY(-7px)}}
    #denji-sprite.denji-walking{animation:denji-walk-bounce .45s ease-in-out infinite}
    @keyframes denji-idle-sway{0%,100%{transform:translateY(0) rotate(0deg)}50%{transform:translateY(-4px) rotate(-1.2deg)}}
    #denji-sprite.denji-idle{animation:denji-idle-sway 2.2s ease-in-out infinite}
    #denji-hud{position:fixed;left:20px;bottom:20px;width:300px;z-index:9998;display:flex;flex-direction:column;gap:8px;font-family:system-ui,-apple-system,sans-serif}
    #denji-card{background:#fff;border:1px solid #ddd;border-radius:12px;padding:16px;font-size:14px;color:#1a1a1a;box-shadow:0 2px 10px rgba(0,0,0,.12)}
    #denji-status{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
    #denji-progress-wrap{width:100%;height:4px;background:#e5e5e5;border-radius:2px;overflow:hidden}
    #denji-progress-fill{height:100%;background:#3b6ef6;transition:width .3s ease;width:0%}
    .denji-opt-btn{margin:4px 8px 4px 0;padding:8px 14px;border:1px solid #ccc;border-radius:8px;background:#fff;cursor:pointer;font-size:14px}
    .denji-omitir-html-btn{display:block;margin-top:4px;font-size:11px;color:#888;background:none;border:none;text-decoration:underline;cursor:pointer;padding:0}
    .denji-opt-btn:hover{background:#f0f0f0}
    .denji-sim-note{font-size:11px;color:#888;margin-top:8px}
    #denji-card pre{background:#f0f0f0;padding:12px;border-radius:8px;font-size:12px;overflow:auto}
  `;
  const styleEl = document.createElement('style');
  styleEl.textContent = css;
  document.head.appendChild(styleEl);

  // ---------- Elementos propios, creados en JS, no dependen del HTML de JC ----------
  const sprite = document.createElement('img');
  sprite.id = 'denji-sprite';
  sprite.alt = 'Denji';
  sprite.src = 'data:image/png;base64,' + SPRITE_IDLE_B64;
  sprite.style.display = 'none'; // oculto hasta que el usuario decida usar el asistente
  document.body.appendChild(sprite);

  const hud = document.createElement('div');
  hud.id = 'denji-hud';
  document.body.appendChild(hud);

  const progressWrap = document.createElement('div');
  progressWrap.id = 'denji-progress-wrap';
  const progressFill = document.createElement('div');
  progressFill.id = 'denji-progress-fill';
  progressWrap.appendChild(progressFill);
  hud.appendChild(progressWrap);

  const statusEl = document.createElement('p');
  statusEl.id = 'denji-status';
  statusEl.setAttribute('aria-live', 'polite');
  statusEl.style.margin = '0';
  statusEl.textContent = 'Iniciando…';
  hud.appendChild(statusEl);

  const nombreEl = document.createElement('p');
  nombreEl.textContent = 'Denji';
  nombreEl.style.cssText = 'margin:0 0 -2px 4px;font-size:11px;font-weight:600;color:#3b6ef6';
  hud.appendChild(nombreEl);

  const card = document.createElement('div');
  card.id = 'denji-card';
  hud.appendChild(card);

  // ---------- Voz ----------
  let voces = [];
  function cargarVoces(){ voces = speechSynthesis.getVoices(); }
  if('speechSynthesis' in window){
    cargarVoces();
    speechSynthesis.onvoiceschanged = cargarVoces;
  }
  function elegirVoz(){
    if(!voces.length) return null;
    const prioridad = ['es-419','es-us','es-mx','es-co','es-pe','es'];
    for(const pref of prioridad){
      const v = voces.find(v => v.lang.toLowerCase().startsWith(pref) && !v.lang.toLowerCase().startsWith('es-es'));
      if(v) return v;
    }
    return voces.find(v => v.lang.toLowerCase().startsWith('es')) || null;
  }
  let modoMovimiento = 'normal';
  let caminando = false;
  let hablando = false;
  let cicloInterval = null;
  let yaSaludo = false;
  let saludando = false; // true mientras dura el saludo inicial, para que nada lo interrumpa
  let asistenteActivo = null; // null = sin decidir, true/false = elección explícita del usuario

  function iniciarCicloCaminata(){
    if(cicloInterval) return; // ya está corriendo, no reiniciar (evita parpadeo)
    let alterna = false;
    cicloInterval = setInterval(() => {
      alterna = !alterna;
      sprite.src = 'data:image/png;base64,' + (alterna ? SPRITE_WALK_B64 : SPRITE_IDLE_B64);
    }, 260);
  }
  function iniciarCicloHabla(){
    if(cicloInterval) return;
    let alterna = false;
    cicloInterval = setInterval(() => {
      alterna = !alterna;
      sprite.src = 'data:image/png;base64,' + (alterna ? SPRITE_TALK_B64 : SPRITE_IDLE_B64);
    }, 180);
  }

  // Saluda agitando el ala unas cuantas veces, y devuelve el control normal al terminar.
  // Se usa una sola vez, cuando Denji aparece por primera vez.
  function reproducirSaludo(mediosCiclos, alTerminar){
    saludando = true;
    if(cicloInterval){ clearInterval(cicloInterval); cicloInterval = null; }
    let alterna = false;
    let contador = 0;
    cicloInterval = setInterval(() => {
      alterna = !alterna;
      sprite.src = 'data:image/png;base64,' + (alterna ? SPRITE_SALUDO_B64 : SPRITE_IDLE_B64);
      contador++;
      if(contador >= mediosCiclos){
        clearInterval(cicloInterval);
        cicloInterval = null;
        saludando = false;
        sprite.src = 'data:image/png;base64,' + SPRITE_IDLE_B64;
        if(alTerminar) alTerminar();
      }
    }, 300);
  }

  function actualizarAnimacion(){
    if(saludando) return; // no interrumpir el saludo en curso
    sprite.classList.remove('denji-idle', 'denji-walking', 'denji-talking');
    if(cicloInterval){ clearInterval(cicloInterval); cicloInterval = null; }
    if(modoMovimiento === 'sin'){
      // prefers-reduced-motion: cero animación, Denji se ve pero no se anima
      sprite.src = 'data:image/png;base64,' + SPRITE_IDLE_B64;
      return;
    }
    if(caminando){
      sprite.classList.add('denji-walking');
      iniciarCicloCaminata();
    } else if(hablando){
      sprite.classList.add('denji-talking');
      iniciarCicloHabla();
    } else {
      sprite.classList.add('denji-idle');
      sprite.src = 'data:image/png;base64,' + SPRITE_IDLE_B64;
    }
  }

  function hablar(texto){
    if(!asistenteActivo) return;
    try{
      if('speechSynthesis' in window){
        speechSynthesis.cancel();
        const u = new SpeechSynthesisUtterance(texto);
        const voz = elegirVoz();
        if(voz){ u.voice = voz; u.lang = voz.lang; } else { u.lang = 'es-419'; }
        u.rate = 1.05; u.pitch = 0.95; u.volume = 1;
        u.onstart = () => { hablando = true; actualizarAnimacion(); };
        u.onend = () => { hablando = false; actualizarAnimacion(); };
        u.onerror = () => { hablando = false; actualizarAnimacion(); };
        speechSynthesis.speak(u);
      }
    }catch(e){}
  }

  // ---------- Reconocimiento de voz (entrada) ----------
  // Aditivo, no reemplaza los botones: si el navegador no soporta esto,
  // simplemente no aparece el botón de micrófono y se sigue usando botones.
  const SpeechRecognitionAPI = window.SpeechRecognition || window.webkitSpeechRecognition;
  const contextoSeguro = location.protocol === 'https:' || location.hostname === 'localhost' || location.hostname === '127.0.0.1';

  const MENSAJES_ERROR_VOZ = {
    'not-allowed': 'Bloqueaste el permiso del micrófono para este sitio. Revisa el ícono de candado en la barra de direcciones.',
    'service-not-allowed': 'El navegador bloqueó el servicio de reconocimiento de voz.',
    'no-speech': 'No escuché nada, intenta de nuevo.',
    'audio-capture': 'No encontré un micrófono conectado.',
    'network': 'Hubo un problema de red al reconocer la voz.'
  };

  function escucharUnaVez(onTranscript, onError){
    const rec = new SpeechRecognitionAPI();
    rec.lang = 'es-419';
    rec.continuous = false;
    rec.interimResults = false;
    rec.maxAlternatives = 1;
    rec.onresult = (e) => onTranscript(normalizar(e.results[0][0].transcript));
    rec.onerror = (e) => { if(onError) onError(e.error); };
    rec.start();
  }

  function crearBotonMic(onTranscript){
    if(!SpeechRecognitionAPI){ return null; } // el navegador no soporta la API, no hay nada que mostrar
    if(!contextoSeguro){
      // Existe la API pero el navegador la bloquea por no ser https/localhost — avisar, no morir en silencio
      const aviso = document.createElement('p');
      aviso.className = 'denji-sim-note';
      aviso.textContent = 'El micrófono necesita que entres por http://localhost:5000, no por la IP de red.';
      return aviso;
    }
    const b = document.createElement('button');
    b.className = 'denji-opt-btn';
    b.textContent = '🎤 Responder por voz';
    b.onclick = () => {
      b.textContent = '🎤 Escuchando…';
      b.disabled = true;
      escucharUnaVez(
        (t) => { b.textContent = '🎤 Responder por voz'; b.disabled = false; onTranscript(t); },
        (errorCode) => {
          b.textContent = '🎤 Responder por voz'; b.disabled = false;
          statusEl.textContent = 'Denji: ' + (MENSAJES_ERROR_VOZ[errorCode] || ('no pude escuchar (' + errorCode + ')'));
        }
      );
    };
    return b;
  }

  const NUMEROS_ES = { cero:0, un:1, uno:1, una:1, dos:2, tres:3, cuatro:4, cinco:5, seis:6, siete:7, ocho:8, nueve:9,
    diez:10, once:11, doce:12, trece:13, catorce:14, quince:15, dieciseis:16, diecisiete:17, dieciocho:18, diecinueve:19, veinte:20 };

  function parseNumeroHablado(texto){
    const limpio = texto.trim();
    if(/^[0-9]+$/.test(limpio)) return parseInt(limpio, 10);
    if(NUMEROS_ES.hasOwnProperty(limpio)) return NUMEROS_ES[limpio];
    const palabras = limpio.split(/\s+/);
    for(let i = palabras.length - 1; i >= 0; i--){
      if(NUMEROS_ES.hasOwnProperty(palabras[i])) return NUMEROS_ES[palabras[i]];
      if(/^[0-9]+$/.test(palabras[i])) return parseInt(palabras[i], 10);
    }
    return null;
  }

  // ---------- Movimiento: lee el HTML de JC tal cual está ----------

  function normalizar(txt){
    return (txt || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
  }
  function buscarPorEtiquetas(etiquetas){
    const candidatos = document.querySelectorAll('body *');
    for(const el of candidatos){
      if(el.children.length > 0) continue;
      if(el.closest('#denji-card') || el.id === 'denji-sprite') continue;
      const texto = normalizar(el.textContent);
      if(!texto) continue;
      if(etiquetas.some(e => texto === normalizar(e))){
        return el.closest('[class]') || el;
      }
    }
    return null;
  }
  function elACoordenadas(el){
    const r = el.getBoundingClientRect();
    // sprite es position:fixed => relativo al viewport. getBoundingClientRect()
    // YA es relativo al viewport. Sumar window.scrollY aquí era el bug: duplicaba
    // el desplazamiento y mandaba a Denji fuera de pantalla en páginas con scroll.
    return { x: Math.max(8, r.left - 60), y: Math.max(8, r.top) };
  }
  sprite.addEventListener('transitionrun', () => { caminando = (modoMovimiento !== 'sin'); actualizarAnimacion(); });
  sprite.addEventListener('transitionend', () => { caminando = false; actualizarAnimacion(); });

  // Etiquetas tal como aparecen en la interfaz real de VólticvS (según el video revisado).
  // Si JC cambia el texto visible de un campo, actualizar acá.
  const ETIQUETAS = {
    aire_acondicionado: ['aire acondicionado'],
    calefaccion_electrica: ['calefaccion electrica'],
    agua_caliente_electrica: ['termotanque / calentador', 'termotanque', 'calentador'],
    secarropas_electrico: ['secarropas electrico'],
    horno_electrico: ['horno o anafe electrico'],
    refrigerador: ['refrigeradores'],
    freezer: ['freezers'],
    tv: ['televisores']
  };

  const WAYPOINTS_REPOSO = [
    { x: 40, y: 0.5 },
    { x: 90, y: 0.42 },
    { x: 55, y: 0.6 },
    { x: 110, y: 0.55 }
  ];
  let waypointIdx = 0;

  function moverA(destinoKey){
    if(!asistenteActivo) return;
    let el = null;
    if(destinoKey){
      el = elementoVisualPara(destinoKey); // 1) mapeo real confirmado con el código de JC
      if(!el) el = document.querySelector('[data-denji-target="' + destinoKey + '"]'); // 2) si algún día lo agrega
      if(!el && ETIQUETAS[destinoKey]) el = buscarPorEtiquetas(ETIQUETAS[destinoKey]); // 3) último recurso, por texto
    }
    let punto;
    if(el){
      punto = elACoordenadas(el);
    } else {
      // sin estación mapeada: deambula entre puntos fijos cerca de HOME, nunca queda estático
      const wp = WAYPOINTS_REPOSO[waypointIdx % WAYPOINTS_REPOSO.length];
      waypointIdx++;
      punto = { x: wp.x, y: window.innerHeight * wp.y };
    }
    sprite.style.transition = (modoMovimiento === 'sin') ? 'none' : 'left 2.2s ease-in-out, top 2.2s ease-in-out';
    sprite.style.left = punto.x + 'px';
    sprite.style.top = punto.y + 'px';
  }

  // ---------- Integración real con el HTML/JS de JC ----------
  // Confirmado con su código fuente: estos son los IDs reales de su formulario,
  // y sus claves de payload ya coinciden con nuestros guarda_en (sin traducir nada).
  const MAPEO_CAMPOS = {
    pais:                    { tipo: 'pais-select', id: 'pais' },
    estado_provincia:        { tipo: 'text',    id: 'selectProvincia' },
    dormitorios:             { tipo: 'counter', id: 'inputDormitorios' },
    ventanas:                { tipo: 'counter', id: 'inputVentanas' },
    habitantes_mayores:      { tipo: 'counter', id: 'inputMayores' },
    habitantes_menores:      { tipo: 'counter', id: 'inputMenores' },
    aire_acondicionado:      { tipo: 'toggle',  id: 'aireAcondicionado',     contenedor: 'equipAC' },
    calefaccion_electrica:   { tipo: 'toggle',  id: 'calefaccionElectrica',  contenedor: 'equipCalef' },
    agua_caliente_electrica: { tipo: 'toggle',  id: 'aguaCalienteElectrica', contenedor: 'equipAgua' },
    secarropas_electrico:    { tipo: 'toggle',  id: 'secarropasElectrico',   contenedor: 'equipSeca' },
    horno_electrico:         { tipo: 'toggle',  id: 'hornoElectrico',        contenedor: 'equipHorno' },
    lavado_frecuencia:       { tipo: 'counter', id: 'lavadoFrecuencia' },
    refrigerador:            { tipo: 'counter', id: 'refrigerador' },
    freezer:                 { tipo: 'counter', id: 'freezer' },
    tv:                      { tipo: 'counter', id: 'tv' },
    tv_frecuencia:           { tipo: 'number',  id: 'tvFrecuencia' } // OJO: este campo es horas DIARIAS, no semanales (ver nota en steps)
    // agua_caliente_tamano, flag_galones, luces_exterior, luces_interior: JC los manda
    // hardcodeados a 0 por ahora, no hay campo real en su UI. Pendiente pedírselo.
  };

  // A qué paso del wizard de JC (1-4) pertenece cada campo, para sincronizar showStep()
  const JC_STEP_POR_CAMPO = {
    pais: 1, estado_provincia: 1,
    dormitorios: 2, ventanas: 2, habitantes_mayores: 2, habitantes_menores: 2,
    aire_acondicionado: 3, calefaccion_electrica: 3, agua_caliente_electrica: 3, secarropas_electrico: 3, horno_electrico: 3,
    lavado_frecuencia: 4, refrigerador: 4, freezer: 4, tv: 4, tv_frecuencia: 4
  };
  let ultimoJCStep = 0;

  function sincronizarPasoJC(guardaEn){
    const paso = JC_STEP_POR_CAMPO[guardaEn];
    if(paso && paso !== ultimoJCStep && typeof window.showStep === 'function'){
      window.showStep(paso);
      ultimoJCStep = paso;
    }
  }

  function elementoVisualPara(guardaEn){
    const campo = MAPEO_CAMPOS[guardaEn];
    if(!campo) return null;
    if(campo.contenedor) return document.getElementById(campo.contenedor);
    const el = document.getElementById(campo.id);
    return el ? (el.closest('.form-group') || el) : null;
  }

  function fijarPaisPorNombre(nombre, intentos){
    intentos = intentos || 0;
    const sel = document.getElementById('pais');
    if(!sel) return false;
    // El <select> de JC se llena async vía fetch('/api/paises'). Mientras solo
    // tenga la opción placeholder ("Cargando países…", value=""), esperamos.
    const opcionesReales = Array.from(sel.options).filter(o => o.value !== '');
    if(opcionesReales.length === 0){
      if(intentos < 20){
        setTimeout(() => fijarPaisPorNombre(nombre, intentos + 1), 150);
      }
      return false;
    }
    const nombreNorm = normalizar(nombre);
    const opt = opcionesReales.find(o => normalizar(o.textContent).includes(nombreNorm));
    if(opt){
      sel.value = opt.value;
      sel.dispatchEvent(new Event('change', { bubbles: true }));
      return true;
    }
    return false;
  }

  function escribirValor(guardaEn, valor){
    const campo = MAPEO_CAMPOS[guardaEn];
    if(!campo) return false;
    if(campo.tipo === 'pais-select'){ return fijarPaisPorNombre(valor); }
    const el = document.getElementById(campo.id);
    if(!el) return false;
    if(campo.tipo === 'toggle'){
      el.checked = !!valor;
      el.dispatchEvent(new Event('change', { bubbles: true }));
    } else {
      el.value = valor;
      el.dispatchEvent(new Event('input', { bubbles: true }));
    }
    return true;
  }

  function leerValorDesdeDOM(campo){
    const el = document.getElementById(campo.id);
    if(!el) return undefined;
    if(campo.tipo === 'toggle') return el.checked ? 1 : 0;
    if(campo.tipo === 'pais-select' || campo.tipo === 'text') return el.value;
    const n = parseInt(el.value, 10);
    return isNaN(n) ? undefined : n;
  }

  // Sentido que faltaba: si el usuario responde directo en el formulario real de
  // JC (sin pasar por Denji), esto lo refleja en respuestas — mismo objeto,
  // sin duplicar el dato en dos lugares que puedan quedar desincronizados.
  // Campos que el usuario ya respondió directo en el HTML de JC (por click real,
  // no por el valor por defecto). Denji los consulta antes de preguntar de nuevo.
  const camposTocados = {};

  const debounceTimers = {};

  function marcarTocadoYAvanzarSiCorresponde(guardaEn, valor, esperar){
    respuestas[guardaEn] = valor;
    camposTocados[guardaEn] = true;
    const stepActual = steps[idx];
    if(!stepActual || stepActual.guarda_en !== guardaEn) return;

    if(!esperar){
      goNext();
      return;
    }
    // Para contadores: esperar un momento tras el último click, para no
    // avanzar a mitad de que el usuario todavía está ajustando el número.
    if(debounceTimers[guardaEn]) clearTimeout(debounceTimers[guardaEn]);
    debounceTimers[guardaEn] = setTimeout(() => {
      const stepAhora = steps[idx];
      if(stepAhora && stepAhora.guarda_en === guardaEn) goNext();
    }, 900);
  }

  function activarSincronizacionDesdeDOM(){
    Object.keys(MAPEO_CAMPOS).forEach(guardaEn => {
      const campo = MAPEO_CAMPOS[guardaEn];
      const el = document.getElementById(campo.id);
      if(!el) return;

      if(campo.tipo === 'counter'){
        // Los contadores de JC escriben el valor por JS al hacer click en +/-,
        // eso NO dispara 'input'. Hay que escuchar el click en los botones mismos.
        document.querySelectorAll('.counter-btn[data-target="' + campo.id + '"]').forEach(btn => {
          btn.addEventListener('click', () => {
            const valor = leerValorDesdeDOM(campo);
            if(valor !== undefined) marcarTocadoYAvanzarSiCorresponde(guardaEn, valor, true);
          });
        });
        return;
      }

      const evento = (campo.tipo === 'toggle' || campo.tipo === 'pais-select') ? 'change' : 'input';
      el.addEventListener(evento, () => {
        const valor = leerValorDesdeDOM(campo);
        if(valor !== undefined) marcarTocadoYAvanzarSiCorresponde(guardaEn, valor, false);
      });
    });
  }

  // "No quiero responder" también disponible directo en el formulario de JC,
  // no solo en la burbuja de Denji. Mismo objeto respuestas para los dos —
  // sin esto, alguien que llena el formulario a mano nunca podía omitir nada.
  function agregarBotonesOmitirEnHTML(){
    Object.keys(MAPEO_CAMPOS).forEach(guardaEn => {
      const campo = MAPEO_CAMPOS[guardaEn];
      if(campo.tipo !== 'counter') return;
      const el = document.getElementById(campo.id);
      if(!el) return;
      const contenedor = el.closest('.counter-input');
      if(!contenedor || contenedor.dataset.denjiOmitirListo) return;
      contenedor.dataset.denjiOmitirListo = '1';

      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'denji-omitir-html-btn';
      btn.textContent = 'No quiero responder';
      let omitido = false;

      btn.addEventListener('click', () => {
        omitido = !omitido;
        contenedor.querySelectorAll('.counter-btn, .counter-value').forEach(elemento => {
          elemento.disabled = omitido;
        });
        contenedor.style.opacity = omitido ? '0.4' : '1';
        btn.textContent = omitido ? 'Sin responder (click para volver a responder)' : 'No quiero responder';
        camposTocados[guardaEn] = true;
        if(omitido){
          delete respuestas[guardaEn];
        } else {
          const valor = leerValorDesdeDOM(campo);
          if(valor !== undefined) respuestas[guardaEn] = valor;
        }
        const stepActual = steps[idx];
        if(stepActual && stepActual.guarda_en === guardaEn){
          goNext();
        }
      });

      contenedor.insertAdjacentElement('afterend', btn);
    });
  }


  const respuestas = {};
  let idx = 0;

  const steps = [
    {id:'consentimiento', tipo:'consentimiento'},
    {id:'accesibilidad', tipo:'accesibilidad'},
    {id:'ubicacion', tipo:'ubicacion'},
    {id:'dormitorios', tipo:'number', texto:'¿Cuántos dormitorios tiene la vivienda? Si es un monoambiente, responde cero.', guarda_en:'dormitorios'},
    {id:'ventanas', tipo:'number', texto:'¿Cuántas ventanas y puertas balcón tiene la vivienda en total?', guarda_en:'ventanas'},
    {id:'habitantes_mayores', tipo:'number', texto:'¿Cuántos habitantes de 18 años o más viven en la vivienda?', guarda_en:'habitantes_mayores'},
    {id:'habitantes_menores', tipo:'number', texto:'¿Cuántos habitantes de 17 años o menos viven en la vivienda?', guarda_en:'habitantes_menores'},
    {id:'aire_acondicionado', tipo:'boolean_int', texto:'¿La vivienda tiene aire acondicionado?', guarda_en:'aire_acondicionado'},
    {id:'calefaccion_electrica', tipo:'boolean_int', texto:'¿La calefacción principal de la vivienda es eléctrica?', guarda_en:'calefaccion_electrica'},
    {id:'agua_caliente_electrica', tipo:'boolean_int', texto:'¿El agua caliente para ducha y lavado de platos se calienta principalmente con electricidad?', guarda_en:'agua_caliente_electrica'},
    {id:'secarropas_electrico', tipo:'boolean_int', texto:'¿La vivienda tiene secarropas eléctrico?', guarda_en:'secarropas_electrico'},
    {id:'horno_electrico', tipo:'boolean_int', texto:'¿El horno principal de la vivienda es eléctrico?', guarda_en:'horno_electrico'},
    {id:'desea_extendida', tipo:'boolean_int', texto:'Con esto ya puedo darte una estimación. ¿Quieres continuar con la versión extendida para afinar el resultado?', guarda_en:'desea_version_extendida', esGate:true},
    // agua_caliente_tamano, flag_galones, luces_exterior y luces_interior quedan
    // FUERA del flujo a propósito: JC todavía no tiene esos campos en su formulario
    // (datosPayload los manda hardcodeados). Preguntarlos igual rompía la regla de
    // "mismas preguntas, misma lógica" — se reactivan cuando JC agregue los campos.
    {id:'lavado_frecuencia', tipo:'number', texto:'¿Cuántas veces por semana lava la ropa?', guarda_en:'lavado_frecuencia', avanzada:true},
    {id:'refrigerador', tipo:'number', texto:'¿Cuántos refrigeradores tiene la vivienda?', guarda_en:'refrigerador', avanzada:true},
    {id:'freezer', tipo:'number', texto:'¿Cuántos freezers independientes del refrigerador tiene la vivienda?', guarda_en:'freezer', avanzada:true},
    // luces_exterior y luces_interior: mismo caso, sin campo real en JC todavía.
    {id:'tv', tipo:'number', texto:'¿Cuántos televisores tiene la vivienda?', guarda_en:'tv', avanzada:true},
    {id:'tv_frecuencia', tipo:'number', texto:'¿Cuántas horas al día está encendido el televisor principal?', guarda_en:'tv_frecuencia', avanzada:true},
    {id:'resumen', tipo:'resumen'}
  ];

  function updateProgress(){
    const total = steps.length - 1;
    progressFill.style.width = Math.round((idx/total)*100) + '%';
  }
  function goNext(){
    idx++;
    let cur = steps[idx];
    while(cur){
      if(cur.avanzada && respuestas.desea_version_extendida === 0){ idx++; cur = steps[idx]; continue; }
      if(cur.guarda_en && camposTocados[cur.guarda_en]){ idx++; cur = steps[idx]; continue; }
      break;
    }
    render();
  }
  function guardarYAvanzar(campo, valor){
    respuestas[campo] = valor;
    escribirValor(campo, valor);
    goNext();
  }
  function preguntarSiOmitir(step){
    const texto = '¿Estás seguro de que quieres enviar sin responder esta pregunta? Quedará como que no la respondiste.';
    statusEl.textContent = 'Denji: ' + texto;
    hablar(texto);
    card.innerHTML = '<p style="margin:0 0 12px">' + texto + '</p>';
    const si = document.createElement('button'); si.className='denji-opt-btn'; si.textContent='No, quiero responderla';
    si.onclick = () => render();
    const no = document.createElement('button'); no.className='denji-opt-btn'; no.textContent='Sí, omitirla';
    no.onclick = () => goNext();
    card.appendChild(si); card.appendChild(no);
  }

  function render(){
    updateProgress();
    const step = steps[idx];
    card.innerHTML = '';
    sincronizarPasoJC(step.guarda_en);
    moverA(MAPEO_CAMPOS[step.guarda_en] || ETIQUETAS[step.guarda_en] ? step.guarda_en : null);

    if(step.tipo === 'consentimiento'){
      // Sin voz, sin movimiento, sin sorpresas. El usuario decide antes de que
      // pase nada — importante para personas con TEA o cualquiera que prefiera
      // no tener un personaje animado hablándole sin haberlo pedido.
      statusEl.textContent = 'Denji: pregunta de consentimiento, en espera';
      card.innerHTML = '<p style="margin:0 0 12px">¿Quieres que el asistente Denji te acompañe hablando y moviéndose por la pantalla mientras completas el formulario, o prefieres hacerlo tú mismo, sin voz ni animaciones?</p>';
      const siBtn = document.createElement('button'); siBtn.className='denji-opt-btn'; siBtn.textContent='Sí, quiero que me guíe';
      siBtn.onclick = () => {
        asistenteActivo = true;
        sprite.style.display = '';
        goNext();
      };
      const noBtn = document.createElement('button'); noBtn.className='denji-opt-btn'; noBtn.textContent='No, prefiero el formulario solo';
      noBtn.onclick = () => {
        asistenteActivo = false;
        mostrarModoSinAsistente();
      };
      card.appendChild(siBtn); card.appendChild(noBtn);
      return;
    }

    if(step.tipo === 'accesibilidad'){
      const reduce = window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches;
      const dark = window.matchMedia && matchMedia('(prefers-color-scheme: dark)').matches;
      modoMovimiento = reduce ? 'sin' : 'normal';
      const resumen = (reduce ? 'movimiento reducido' : 'movimiento normal') + ', ' + (dark ? 'modo oscuro' : 'modo claro');
      const texto = '¡Hola! Soy Denji. Detecté que tu sistema tiene ' + resumen + '. Voy a usar esta configuración para que la experiencia sea más cómoda. ¿Quieres mantenerla así?';
      statusEl.textContent = 'Denji: ' + texto;
      if(!yaSaludo && !reduce){
        yaSaludo = true;
        reproducirSaludo(6, () => hablar(texto));
      } else {
        yaSaludo = true;
        hablar(texto);
      }
      card.innerHTML = '<p style="margin:0 0 12px">' + texto + '</p>';
      const si = document.createElement('button'); si.className='denji-opt-btn'; si.textContent='Sí, mantenerla';
      si.onclick = () => guardarYAvanzar('config_accesibilidad', resumen);
      const no = document.createElement('button'); no.className='denji-opt-btn'; no.textContent='No, usar valores por defecto';
      no.onclick = () => { modoMovimiento='normal'; guardarYAvanzar('config_accesibilidad', 'por_defecto'); };
      card.appendChild(si); card.appendChild(no);
      return;
    }

    if(step.tipo === 'ubicacion'){
      detectarUbicacionReal();
      return;
    }

    if(step.tipo === 'number'){
      statusEl.textContent = 'Denji: ' + step.texto;
      hablar(step.texto);
      card.innerHTML = '<p style="margin:0 0 14px">' + step.texto + '</p>' +
        '<div style="display:flex;align-items:center;gap:10px">' +
        '<button class="denji-opt-btn" id="denji-num-menos" style="width:36px;font-size:18px;padding:6px 0">−</button>' +
        '<span id="denji-num-valor" style="min-width:30px;text-align:center;font-size:18px;font-weight:600">0</span>' +
        '<button class="denji-opt-btn" id="denji-num-mas" style="width:36px;font-size:18px;padding:6px 0">+</button>' +
        '</div><div style="margin-top:14px">' +
        '<button class="denji-opt-btn" id="denji-num-submit">Confirmar</button>' +
        '<button class="denji-opt-btn" id="denji-num-omitir">No quiero responder</button></div>';
      let valor = 0;
      const valorEl = document.getElementById('denji-num-valor');
      document.getElementById('denji-num-menos').onclick = () => { if(valor>0){ valor--; valorEl.textContent=valor; } };
      document.getElementById('denji-num-mas').onclick = () => { valor++; valorEl.textContent=valor; };
      document.getElementById('denji-num-submit').onclick = () => guardarYAvanzar(step.guarda_en, valor);
      document.getElementById('denji-num-omitir').onclick = () => preguntarSiOmitir(step);
      const micNum = crearBotonMic((transcript) => {
        const n = parseNumeroHablado(transcript);
        if(n === null){ statusEl.textContent = 'Denji: no entendí el número, intenta de nuevo o usa los botones'; return; }
        guardarYAvanzar(step.guarda_en, n);
      });
      if(micNum) card.querySelector('div:last-child').appendChild(micNum);
      return;
    }

    if(step.tipo === 'boolean_int'){
      statusEl.textContent = 'Denji: ' + step.texto;
      hablar(step.texto);
      card.innerHTML = '<p style="margin:0 0 12px">' + step.texto + '</p>';
      const si = document.createElement('button'); si.className='denji-opt-btn'; si.textContent='Sí';
      si.onclick = () => guardarYAvanzar(step.guarda_en, 1);
      const no = document.createElement('button'); no.className='denji-opt-btn'; no.textContent='No';
      no.onclick = () => guardarYAvanzar(step.guarda_en, 0);
      card.appendChild(si); card.appendChild(no);
      const micBool = crearBotonMic((transcript) => {
        if(['si', 'correcto'].includes(transcript)) guardarYAvanzar(step.guarda_en, 1);
        else if(['no', 'incorrecto'].includes(transcript)) guardarYAvanzar(step.guarda_en, 0);
        else statusEl.textContent = 'Denji: no te entendí, intenta de nuevo o usa los botones';
      });
      if(micBool) card.appendChild(micBool);
      return;
    }

    if(step.tipo === 'choice'){
      statusEl.textContent = 'Denji: ' + step.texto;
      hablar(step.texto);
      card.innerHTML = '<p style="margin:0 0 12px">' + step.texto + '</p>';
      step.opciones.forEach(op => {
        const b = document.createElement('button'); b.className='denji-opt-btn'; b.textContent=op.label;
        b.onclick = () => guardarYAvanzar(step.guarda_en, op.valor);
        card.appendChild(b);
      });
      const micChoice = crearBotonMic((transcript) => {
        const match = step.opciones.find(op => normalizar(op.label) === transcript);
        if(match) guardarYAvanzar(step.guarda_en, match.valor);
        else statusEl.textContent = 'Denji: no te entendí, intenta de nuevo o usa los botones';
      });
      if(micChoice) card.appendChild(micChoice);
      return;
    }

    if(step.tipo === 'resumen'){
      const btnSubmit = document.getElementById('btnSubmit');
      const resultadosEl = document.getElementById('resultados');
      if(btnSubmit && resultadosEl){
        const texto = 'Listo, ya tengo todo. Voy a calcular tu consumo, dame un segundo.';
        statusEl.textContent = 'Denji: ' + texto;
        hablar(texto);
        card.innerHTML = '<p style="margin:0 0 10px">' + texto + '</p>';
        btnSubmit.click(); // dispara el cálculo real (fetch async) de VólticvS
        esperarYLeerResultados(resultadosEl);
      } else {
        // fallback: si no encontró los elementos reales (ej. probando este script fuera de la página de JC)
        const texto = 'Te hago el resumen.';
        statusEl.textContent = 'Denji: ' + texto;
        hablar(texto);
        card.innerHTML = '<p style="margin:0 0 10px">' + texto + '</p><pre>' + JSON.stringify(respuestas, null, 2) + '</pre>';
      }
      return;
    }
  }

  // El submit de JC es asíncrono (fetch a su API). Esto observa cuándo su
  // sección de resultados deja de estar oculta, y recién ahí lee lo que
  // JC realmente calculó — nunca inventamos un resumen propio.
  function esperarYLeerResultados(resultadosEl){
    let resuelto = false;
    const timeoutId = setTimeout(() => {
      if(resuelto) return;
      resuelto = true;
      observer.disconnect();
      const texto = 'El cálculo está tardando más de lo normal. Revisa la pantalla, puede que haya un error.';
      statusEl.textContent = 'Denji: ' + texto;
      hablar(texto);
    }, 15000);

    const observer = new MutationObserver(() => {
      if(resuelto) return;
      if(!resultadosEl.hidden){
        resuelto = true;
        clearTimeout(timeoutId);
        observer.disconnect();
        leerResultadosReales();
      }
    });
    observer.observe(resultadosEl, { attributes: true, attributeFilter: ['hidden'] });
  }

  function leerResultadosReales(){
    const kwh = document.getElementById('metricaKwh')?.textContent?.trim();
    const ahorro = document.getElementById('metricaAhorro')?.textContent?.trim();
    const items = Array.from(document.querySelectorAll('#listaRecomendaciones li')).map(li => li.textContent.trim());

    let texto = 'Listo, aquí está tu resultado.';
    if(kwh) texto += ' Tu consumo estimado es ' + kwh + '.';
    if(ahorro) texto += ' Tu ahorro potencial es ' + ahorro + '.';
    if(items.length){
      texto += ' Mis recomendaciones: ' + items.join('. ');
    }

    statusEl.textContent = 'Denji: listo, revisa tus recomendaciones';
    hablar(texto);
    card.innerHTML = '<p style="margin:0 0 10px">Listo, aquí está tu resultado:</p>' +
      (kwh ? '<p style="margin:0 0 4px"><strong>Consumo:</strong> ' + kwh + '</p>' : '') +
      (ahorro ? '<p style="margin:0 0 8px"><strong>Ahorro:</strong> ' + ahorro + '</p>' : '') +
      (items.length ? '<ul style="margin:0;padding-left:18px">' + items.map(i => '<li>' + i + '</li>').join('') + '</ul>' : '');
  }

  function detectarUbicacionReal(){
    statusEl.textContent = 'Denji: Detectando tu ubicación…';
    card.innerHTML = '<p style="margin:0 0 8px">Detectando tu ubicación…</p><p class="denji-sim-note">Tu navegador te va a pedir permiso para usar tu ubicación.</p>';

    if(!('geolocation' in navigator)){
      renderUbicacionManual();
      return;
    }

    navigator.geolocation.getCurrentPosition(
      (pos) => {
        const lat = pos.coords.latitude;
        const lon = pos.coords.longitude;
        fetch('https://nominatim.openstreetmap.org/reverse?format=json&lat=' + lat + '&lon=' + lon + '&zoom=10&addressdetails=1')
          .then(r => r.json())
          .then(data => {
            const addr = data.address || {};
            const comuna = addr.city || addr.town || addr.village || addr.municipality || addr.county || '';
            const region = addr.state || addr.region || '';
            const pais = addr.country || '';
            if(!comuna && !region && !pais){ renderUbicacionManual(); return; }
            mostrarConfirmacionUbicacion(comuna, region, pais);
          })
          .catch(() => renderUbicacionManual());
      },
      () => {
        // permiso denegado, tiempo agotado, u otro error del navegador
        const texto = 'No pude acceder a tu ubicación. Vamos a ingresarla manualmente.';
        statusEl.textContent = 'Denji: ' + texto;
        hablar(texto);
        renderUbicacionManual();
      },
      { timeout: 8000 }
    );
  }

  function mostrarConfirmacionUbicacion(comuna, region, pais){
    const texto = 'Detecté que estás en ' + [comuna, region, pais].filter(Boolean).join(', ') + '. ¿Es correcto?';
    statusEl.textContent = 'Denji: ' + texto;
    hablar(texto);
    card.innerHTML = '<p style="margin:0 0 4px">' + texto + '</p>';
    const si = document.createElement('button'); si.className='denji-opt-btn'; si.textContent='Sí, es correcto';
    si.onclick = () => {
      respuestas.pais = pais; respuestas.estado_provincia = region; respuestas.comuna = comuna;
      escribirValor('pais', pais);
      escribirValor('estado_provincia', region);
      goNext();
    };
    const no = document.createElement('button'); no.className='denji-opt-btn'; no.textContent='No, corregir';
    no.onclick = () => renderUbicacionManual();
    card.appendChild(si); card.appendChild(no);
  }

  function mostrarModoSinAsistente(){
    progressWrap.style.display = 'none';
    nombreEl.style.display = 'none';
    statusEl.textContent = 'Denji: en espera, sin interactuar';
    card.innerHTML = '<p style="margin:0 0 8px;font-size:12px;color:#666">Puedes llenar el formulario tú mismo, sin el asistente. Si cambias de opinión:</p>';
    const activarBtn = document.createElement('button');
    activarBtn.className = 'denji-opt-btn';
    activarBtn.textContent = 'Activar asistente Denji';
    activarBtn.onclick = () => {
      asistenteActivo = true;
      sprite.style.display = '';
      progressWrap.style.display = '';
      nombreEl.style.display = '';
      goNext();
    };
    card.appendChild(activarBtn);
  }

  function renderUbicacionManual(){
    card.innerHTML = '<p style="margin:0 0 8px">¿En qué país te encuentras?</p><input id="denji-pais" type="text" style="width:200px" />' +
      '<p style="margin:12px 0 8px">¿En qué estado o provincia?</p><input id="denji-estado" type="text" style="width:200px" />' +
      '<p style="margin:12px 0 8px">¿En qué comuna o ciudad?</p><input id="denji-comuna" type="text" style="width:200px" />' +
      '<div style="margin-top:12px"><button class="denji-opt-btn" id="denji-ubi-submit">Continuar</button></div>';
    document.getElementById('denji-ubi-submit').onclick = () => {
      respuestas.pais = document.getElementById('denji-pais').value || 'No especificado';
      respuestas.estado_provincia = document.getElementById('denji-estado').value || 'No especificado';
      respuestas.comuna = document.getElementById('denji-comuna').value || 'No especificado';
      escribirValor('pais', respuestas.pais);
      escribirValor('estado_provincia', respuestas.estado_provincia);
      goNext();
    };
  }

  // ---------- Auto-inicio ----------
  // Volti se mantiene visible: funciona como buen complemento de Denji, no
  // como duplicado a esconder. Si en el futuro se agrega la elección real de
  // "modo sin interacción", ahí se decide cuál de los dos se oculta.
  // El label de "Consumo eléctrico mensual (kWh)" queda fijo en el HTML de JC,
  // pero el toggle real (#flagAnual) puede decir mensual o anual. Esto los
  // mantiene sincronizados sin tocar el HTML de JC.
  function sincronizarLabelConsumo(){
    const flagAnual = document.getElementById('flagAnual');
    const label = document.querySelector('label[for="inputConsumo"]');
    if(!flagAnual || !label) return;
    const iconoEl = label.querySelector('.label-badge');
    function actualizar(){
      const periodo = flagAnual.checked ? 'anual' : 'mensual';
      label.textContent = '';
      if(iconoEl) label.appendChild(iconoEl);
      label.appendChild(document.createTextNode(' Consumo eléctrico ' + periodo + ' (kWh)'));
    }
    flagAnual.addEventListener('change', actualizar);
    actualizar();
  }

  activarSincronizacionDesdeDOM();
  sincronizarLabelConsumo();
  agregarBotonesOmitirEnHTML();
  actualizarAnimacion();
  if(document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', render);
  } else {
    render();
  }
})();
